package com.leenex.exam.platform.web;

import java.security.SecureRandom;
import java.time.Clock;
import java.util.UUID;

/**
 * Time-ordered UUID version 7 (RFC 9562), generated by the application (ADR-003).
 *
 * <p>The first 48 bits are the Unix time in milliseconds, so new keys sort after old ones and keep B-tree indexes
 * compact. The remaining 74 bits are random.
 */
public final class UuidV7 {

    private static final SecureRandom RANDOM = new SecureRandom();

    private UuidV7() {
    }

    public static UUID generate() {
        return generate(Clock.systemUTC());
    }

    static UUID generate(Clock clock) {
        long millis = clock.millis();
        byte[] random = new byte[10];
        RANDOM.nextBytes(random);

        long msb = (millis & 0xFFFF_FFFF_FFFFL) << 16;           // 48-bit timestamp
        msb |= 0x7000L;                                          // version 7
        msb |= ((random[0] & 0x0FL) << 8) | (random[1] & 0xFFL); // 12 random bits (rand_a)

        long lsb = 0x8000_0000_0000_0000L;                       // variant 10
        lsb |= (random[2] & 0x3FL) << 56;
        for (int i = 3; i < 10; i++) {
            lsb |= (random[i] & 0xFFL) << (8 * (9 - i));
        }
        return new UUID(msb, lsb);
    }

    /** Milliseconds since the epoch encoded in a version-7 UUID. */
    public static long timestampMillis(UUID uuid) {
        if (uuid.version() != 7) {
            throw new IllegalArgumentException("Not a version 7 UUID: " + uuid);
        }
        return uuid.getMostSignificantBits() >>> 16;
    }
}
